(function() {
  const svgElement = document.currentScript.closest('svg');
  const dataElement = svgElement.querySelector('#aws-architecture-data');
  if (!dataElement) return;

  try {
    const data = JSON.parse(dataElement.textContent);
    console.log('[AWS Architecture Data] Loaded:', data.metadata.title);

    // Initialize rendering with data
    function renderArchitecture() {
      // Data-driven rendering can extend here
      // Calculate positions from data.config.layout
      // Apply styles from data.config.styling
      // Render services from data.data.services
    }

    // Render on load
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', renderArchitecture);
    } else {
      renderArchitecture();
    }
  } catch (e) {
    console.error('[AWS Architecture] Invalid JSON:', e.message);
  }
})();
